"""
make_quiz_L1.py -- quiz bank of Lecture 1 (EN + RO) -> assets/quizzes/l1.js. Numbers come from L1_numbers.json only.
correct = index (0-3) of the right option in the original order; incorrectExplanation never names an option letter.
Run:  python3 lectures/L1/make_quiz_L1.py
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, "..", ".."))
N = json.load(open(os.path.join(HERE, "L1_numbers.json")))


def g(key):
    v = N
    for p in key.split("."):
        v = v[p]
    return v


def f(key, spec, lang):
    s = format(g(key), spec)
    if lang == "ro":
        s = s.replace(",", " ").replace(".", ",")
    else:
        s = s.replace(",", " ") if "," in spec else s
    return s.replace("-", "−") if s.startswith("-") else s


QS = []


def q(correct, en, ro):
    QS.append({"correct": correct,
               "en": dict(zip(("title", "text", "options", "correctExplanation", "incorrectExplanation"), en)),
               "ro": dict(zip(("title", "text", "options", "correctExplanation", "incorrectExplanation"), ro))})


E, R = (lambda k, s: f(k, s, "en")), (lambda k, s: f(k, s, "ro"))

q(1, ("Logistic regression as a neuron",
      "Which combination of output activation and loss makes a one-neuron network identical to logistic regression?",
      ["Identity output and mean squared error", "Sigmoid output and cross-entropy (Bernoulli negative log-likelihood)",
       "Step function and the perceptron criterion", "ReLU output and mean absolute error"],
      "A sigmoid maps the score to a probability and the cross-entropy is the Bernoulli negative log-likelihood: maximising it is exactly logistic regression.",
      "Logistic regression is a maximum-likelihood model for a binary target: the output must be a probability (sigmoid) and the loss the Bernoulli negative log-likelihood."),
  ("Regresia logistică drept neuron",
   "Ce combinație între activarea de ieșire și pierdere face ca o rețea cu un singur neuron să fie identică cu regresia logistică?",
   ["Ieșire identitate și eroarea pătratică medie", "Ieșire sigmoidă și entropia încrucișată (minus log-verosimilitatea Bernoulli)",
    "Funcția treaptă și criteriul perceptronului", "Ieșire ReLU și eroarea absolută medie"],
   "Sigmoida transformă scorul într-o probabilitate, iar entropia încrucișată este minus log-verosimilitatea Bernoulli: minimizarea ei este exact regresia logistică.",
   "Regresia logistică este un model de verosimilitate maximă pentru o țintă binară: ieșirea trebuie să fie o probabilitate (sigmoidă), iar pierderea, minus log-verosimilitatea Bernoulli."))
q(2, ("Gradient of the logistic loss",
      "For one observation with input $\\mathbf x_i$, label $y_i$ and predicted probability $p_i$, what is the gradient of the cross-entropy with respect to the weights?",
      ["$y_i\\,\\mathbf x_i$", "$p_i(1-p_i)\\,\\mathbf x_i$", "$(p_i-y_i)\\,\\mathbf x_i$", "$(p_i-y_i)^2\\,\\mathbf x_i$"],
      "The derivative of the loss with respect to the score is $p_i-y_i$; the chain rule multiplies it by the input, $\\partial z_i/\\partial\\mathbf w=\\mathbf x_i$.",
      "The sigmoid's derivative $p(1-p)$ cancels against the derivative of the logarithms, leaving the error $p_i-y_i$ times the input. The same 'error times input' form appears in every layer of backpropagation."),
  ("Gradientul pierderii logistice",
   "Pentru o observație cu intrarea $\\mathbf x_i$, eticheta $y_i$ și probabilitatea prezisă $p_i$, cît este gradientul entropiei încrucișate în raport cu ponderile?",
   ["$y_i\\,\\mathbf x_i$", "$p_i(1-p_i)\\,\\mathbf x_i$", "$(p_i-y_i)\\,\\mathbf x_i$", "$(p_i-y_i)^2\\,\\mathbf x_i$"],
   "Derivata pierderii în raport cu scorul este $p_i-y_i$; regula de derivare a funcțiilor compuse o înmulțește cu intrarea, $\\partial z_i/\\partial\\mathbf w=\\mathbf x_i$.",
   "Derivata sigmoidei, $p(1-p)$, se simplifică cu derivata logaritmilor și rămîne eroarea $p_i-y_i$ înmulțită cu intrarea. Aceeași formă „eroare ori intrare” apare în fiecare strat la propagarea înapoi."))
